"""Shared fixtures: the author's example as input (D3)."""
import os
from dataclasses import dataclass
from pathlib import Path

import ipxact
import pytest
import xactflow
from xactflow import Library

ROOT = Path(__file__).resolve().parents[1]
# The example's clone, named only by RTLGEN_EXAMPLE (D3); None when it is not set.
_EXAMPLE_ENV = os.environ.get("RTLGEN_EXAMPLE")
EXAMPLE = Path(_EXAMPLE_ENV).expanduser() if _EXAMPLE_ENV else None
GENERATED = ROOT / "build" / "soc_a"

# What the exporter writes for the example.
EXPECTED_SOC_A = (
	"// Generated by rtlgen from example.org:design:soc_a.design:1.0. Do not edit.\n"
	"module soc_a;\n"
	"  cpu cpu ();\n"
	"  apb_interconnect bus ();\n"
	"  uart #(\n"
	"    .BAUDRATE(9600)\n"
	"  ) uart ();\n"
	"  gpio #(\n"
	"    .DATA_W(16)\n"
	"  ) gpio ();\n"
	"  debug debug ();\n"
	"endmodule\n"
)


@dataclass
class Example:
	libs: list  # the folders the library is scanned from
	generated: Path  # the folder with the generated design and component
	design_file: Path  # the design given to the exporter


@pytest.fixture
def example():
	"""The example's input files. Skips when they are missing (see docs/inputs.md)."""
	if EXAMPLE is None:
		pytest.skip("RTLGEN_EXAMPLE is not set: point it at a clone of the example (docs/inputs.md)")
	if not (EXAMPLE / "xml_to_design").is_dir():
		pytest.skip(f"the example is not at {EXAMPLE} (RTLGEN_EXAMPLE)")
	design_file = GENERATED / "example.org_design_soc_a.design_1.0.xml"
	if not design_file.is_file():
		pytest.skip(f"{design_file} is missing: generate it as docs/inputs.md says")
	return Example(
		libs=[EXAMPLE / "xml_to_design", EXAMPLE / "bus_definitions", GENERATED],
		generated=GENERATED,
		design_file=design_file,
	)


@pytest.fixture
def library(example):
	"""A fresh library of the example, with the soc_a design as its one target."""
	library = Library.scan(*example.libs)
	assert library.add_file(example.design_file, target=True)
	return library


@pytest.fixture
def linked(library):
	"""The soc_a design linked against the example's library, fresh for each test."""
	design = next(library.targets(ipxact.Design))
	return xactflow.link(design, library)
